insert into public.products (id, name, house, type, size, price, image, tagline, story, notes, ingredients, feel, featured, world, sound, nozzle, sort) values
('giberish-signature', 'Giberish Signature', 'Giberish', 'attar', 'Attar', null, 'assets/img/hd/giberish-signature.webp', 'Pure. Rare. Timeless.', 'Our first and quietest creation. Kept in a domed vessel the way old perfumers kept their most precious oils. It isn’t something you wear for others. You wear it for the moment after the noise stops.', '{"top":["Saffron"],"heart":["Rose","Oud"],"base":["Sandalwood","Amber"]}'::jsonb, array['oud', 'rose', 'saffron', 'sandalwood', 'amber']::text[], array['Still', 'Whole', 'Timeless']::text[], true, null, null, '[0.5,0.02]'::jsonb, 10),
('barakkat-rouge-540', 'Barakkat Rouge 540', 'Giberish Luxury Perfumes', 'perfume', '60 ml · Eau de Parfum', 600, 'assets/img/hd/barakkat-rouge.webp', 'Luxury in every drop.', 'Inspired by the legendary Rouge 540. Saffron threads catch the light, jasmine opens like a held breath, and cedarwood and amber stay on your skin like a warm hand. People will ask what you’re wearing.', '{"top":["Saffron"],"heart":["Jasmine"],"base":["Amber","Cedarwood"]}'::jsonb, array['saffron', 'jasmine', 'amber', 'cedar', 'rose']::text[], array['Radiant', 'Magnetic', 'Unforgettable']::text[], true, 'bazaar', null, '[0.5,0.02]'::jsonb, 20),
('kaaf', 'Kaaf', 'Ahmad Al Maghribi', 'perfume', '60 ml · Extrait de Parfum', null, 'assets/img/hd/kaaf.webp', 'Not just a fragrance. A statement.', 'A journey into the soul of Arabian heritage. Kaaf opens bright with citrus, spice and cardamom, then deepens into oud, leather and florals before settling into amber, musk, patchouli and vanilla. It lasts 10 to 12 hours, long after you’ve left.', '{"top":["Citrus","Spices","Cardamom"],"heart":["Oud","Leather","Floral"],"base":["Amber","Musk","Patchouli","Vanilla"]}'::jsonb, array['citrus', 'cardamom', 'oud', 'leather', 'amber', 'vanilla']::text[], array['Bold', 'Refined', 'Unforgettable']::text[], true, null, null, '[0.5,0.02]'::jsonb, 30),
('fahad', 'Fahad', 'Lattafa', 'perfume', '60 ml · Eau de Parfum', 600, 'assets/img/hd/fahad.webp', 'A fragrance that speaks before you do.', 'Bold, masculine, timeless. Fahad means “leopard”, and it moves like one: quiet, certain and impossible to ignore. We wore it for weeks before we chose it for you.', '{"top":["Cardamom"],"heart":["Leather","Oud"],"base":["Amber"]}'::jsonb, array['cardamom', 'leather', 'oud', 'amber', 'smoke']::text[], array['Confident', 'Grounded', 'Powerful']::text[], true, 'desert', null, '[0.5,0.02]'::jsonb, 40),
('white-oud', 'White Oud', 'Eau de Parfum', 'perfume', 'Eau de Parfum', 470, 'assets/img/hd/white-oud.webp', 'Oud, dressed in silk.', 'For those who think oud is too heavy. Here the dark wood is softened with rose, vanilla and clean musk. It’s gentle enough for the office and memorable enough for the evening.', '{"top":["Rose"],"heart":["Oud"],"base":["Vanilla","White Musk"]}'::jsonb, array['oud', 'rose', 'vanilla', 'musk']::text[], array['Soft', 'Elegant', 'Serene']::text[], false, null, null, '[0.5,0.02]'::jsonb, 50),
('viking-creed', 'Viking Creed', 'Eau de Parfum', 'perfume', 'Eau de Parfum', 470, 'assets/img/hd/viking-creed.webp', 'For the one who leads.', 'Bright citrus and a trace of smoked wood, like a fire on a cold northern shore. Wear it on days when you need to walk in first and speak last.', '{"top":["Citrus"],"heart":["Smoked Birch"],"base":["Musk","Sandalwood"]}'::jsonb, array['citrus', 'smoke', 'musk', 'sandalwood']::text[], array['Fearless', 'Fresh', 'Driven']::text[], false, 'monsoon', null, '[0.5,0.02]'::jsonb, 60),
('liquid-burn', 'Liquid Burn', 'French Avenue', 'perfume', '60 ml · Eau de Parfum', 600, 'assets/img/hd/liquid-burn.webp', 'More than a fragrance. It’s a feeling.', 'A powerful blend of spices, woods and warmth. Saffron and black pepper strike first like a match, then smouldering woods and amber glow on for hours. Liquid Burn is for those who leave a lasting impression.', '{"top":["Saffron","Black Pepper"],"heart":["Spices"],"base":["Woods","Amber"]}'::jsonb, array['saffron', 'cardamom', 'smoke', 'cedar', 'amber']::text[], array['Bold', 'Intense', 'Lasting']::text[], false, null, 'fire', '[0.5,0.02]'::jsonb, 70),
('green-irish', 'Green Irish', 'Giberish', 'perfume', '60 ml · Men’s Perfume', 600, 'assets/img/hd/green-irish.webp', 'Fresh. Refined. Timeless.', 'Rain on green hills, a walk through wet grass, a freshly pressed shirt. Green Irish opens with bright citrus and crushed leaves, then settles into a soft, woody calm. Fresh enough for every day, refined enough to be remembered.', '{"top":["Citrus","Green Leaves"],"heart":["Violet Leaf","Iris"],"base":["Sandalwood","Ambergris"]}'::jsonb, array['citrus', 'green', 'sandalwood', 'musk', 'amber']::text[], array['Fresh', 'Refined', 'Timeless']::text[], false, null, 'forest', '[0.5,0.02]'::jsonb, 80),
('ajmal-1001-night', '1001 Night', 'Ajmal · Attar', 'attar', '3 ml · Attar', 330, 'assets/img/hd/ajmal-1001-night.webp', 'A story that never ends.', 'Like Scheherazade’s tales, this attar unfolds slowly: rose at dusk, oud at midnight, and amber when the lamps burn low. One touch on the wrist is enough.', '{"top":["Saffron"],"heart":["Rose"],"base":["Oud","Amber"]}'::jsonb, array['rose', 'oud', 'amber', 'saffron']::text[], array['Dreamy', 'Romantic', 'Mysterious']::text[], false, 'garden', null, '[0.5,0.02]'::jsonb, 90),
('al-bakhoor', 'Al-Bakhoor', 'Attar', 'attar', '6 ml · Attar', 300, 'assets/img/hd/al-bakhoor.webp', 'The smoke of a thousand prayers.', 'The scent of incense curling up through an old courtyard. Smoky, resinous and calming, it’s the attar you reach for before you sit in silence.', '{"top":["Incense"],"heart":["Oud"],"base":["Sandalwood","Amber"]}'::jsonb, array['smoke', 'oud', 'sandalwood', 'amber']::text[], array['Sacred', 'Calm', 'Centred']::text[], false, null, null, '[0.5,0.02]'::jsonb, 100),
('hajar-al-aswad', 'Hajar Al Aswad', 'Attar', 'attar', '3 ml · Attar', 330, 'assets/img/hd/hajar-al-aswad.webp', 'Dark, deep, devoted.', 'Named after the black stone, this attar is warm and resinous with a quiet sweetness at its core. It sits close to the skin and stays there all day like a prayer.', '{"top":["Saffron"],"heart":["Oud","Leather"],"base":["Amber","Musk"]}'::jsonb, array['oud', 'amber', 'musk', 'leather', 'saffron']::text[], array['Devoted', 'Warm', 'Deep']::text[], false, null, null, '[0.5,0.02]'::jsonb, 110),
('musk-gold', 'Musk Gold Premium', 'Attar', 'attar', '3 ml · Attar', 330, 'assets/img/hd/musk-gold.webp', 'Like clean skin in sunlight.', 'Soft white musk, a little vanilla and a glow of amber. It smells like your own skin on its best day. People lean in without knowing why.', '{"top":["Jasmine"],"heart":["White Musk"],"base":["Vanilla","Amber"]}'::jsonb, array['musk', 'vanilla', 'amber', 'jasmine']::text[], array['Pure', 'Tender', 'Glowing']::text[], false, 'silk', null, '[0.5,0.02]'::jsonb, 120),
('mukhallat-malaki', 'Mukhallat Malaki', 'Attar', 'attar', '6 ml · Attar', 300, 'assets/img/hd/mukhallat-malaki.webp', 'A royal blend.', '“Mukhallat” means blend and “Malaki” means royal. Rose, saffron, oud and sandalwood are layered the way palace perfumers did it: richly, patiently and without hurry.', '{"top":["Saffron"],"heart":["Rose"],"base":["Oud","Sandalwood"]}'::jsonb, array['rose', 'saffron', 'oud', 'sandalwood']::text[], array['Regal', 'Rich', 'Gracious']::text[], false, 'bazaar', null, '[0.5,0.02]'::jsonb, 130),
('celoud', 'Celoud', 'Naseem · Attar', 'attar', '3 ml · Stick bottle', 250, 'assets/img/hd/celoud.webp', 'Feel the royal touch.', 'A rich, royal oud in a new stick bottle that slips into any pocket. Agarwood and white blossoms make a small, private luxury you can carry all day.', '{"top":["Jasmine"],"heart":["Rose"],"base":["Oud"]}'::jsonb, array['oud', 'jasmine', 'rose']::text[], array['Royal', 'Fresh', 'Assured']::text[], false, null, null, '[0.64,0.01]'::jsonb, 140),
('bakhoor-dani', 'Bakhoor Dani', 'Giberish Home Ritual', 'ritual', 'Incense burner', 550, 'assets/img/hd/bakhoor-dani.webp', 'Bring the temple home.', 'A hand-finished burner for bakhoor and oud chips. Light it at dusk, let the smoke find every corner and watch your home slow down. This is where every Giberish ritual begins.', '{"top":["Incense"],"heart":["Oud"],"base":["Amber"]}'::jsonb, array['smoke', 'oud', 'amber', 'sandalwood']::text[], array['Peaceful', 'Sacred', 'Home']::text[], false, null, null, '[0.5,0.07]'::jsonb, 150)
